"""Complete named medical short-answer and practical records with textbook-level facts."""
import os
from repair_reviewed_medical_items import apply_one, snapshot
from repair_question_bank import PROJECT

ANSWERS = {
'35176e30-7bf8-4a09-bfd1-1553294ef742': """Pneumocystis jirovecii is an opportunistic fungus that causes Pneumocystis pneumonia, especially in patients with advanced HIV infection or other causes of impaired cellular immunity. It produces fever, dry cough, progressive dyspnoea and hypoxaemia, often with bilateral ground-glass opacities. Diagnosis is by detection of the organism or its DNA in induced sputum or bronchoalveolar lavage; serum beta-D-glucan is supportive but not specific. First-line treatment and prophylaxis use trimethoprim-sulfamethoxazole. Add corticosteroids for moderate or severe hypoxaemia in HIV-associated disease.""",
'3a7a378d-4e06-40ff-a446-4b4fad5855da': """Cryptosporidium parvum is an intestinal protozoan transmitted by ingestion of oocysts in contaminated water or food. It causes watery diarrhoea, which can be prolonged and severe in patients with advanced HIV infection. Diagnosis includes stool antigen assays, PCR or modified acid-fast microscopy of oocysts. Management centres on oral or intravenous rehydration; nitazoxanide can be useful in immunocompetent patients. Immune restoration with antiretroviral therapy is crucial in HIV-associated cryptosporidiosis.""",
'4d2a70db-c622-4e31-903d-74cfaaf64aad': """Toxoplasma gondii is an obligate intracellular protozoan acquired through undercooked meat containing tissue cysts, oocysts shed by cats, or transplacental transmission. Immunocompetent infection is often asymptomatic; congenital disease can produce chorioretinitis, intracranial calcification and hydrocephalus. Reactivation in immunosuppressed patients can cause focal encephalitis. Diagnosis uses serology and, when appropriate, PCR or neuroimaging. Severe toxoplasmosis is commonly treated with pyrimethamine, sulfadiazine and folinic acid.""",
'54d935d9-1026-4b12-bd73-189fe22e2274': """Aspergillus fumigatus is a mould with septate hyphae showing acute-angle branching in tissue. It can cause allergic bronchopulmonary aspergillosis, aspergilloma in a pre-existing lung cavity, or invasive disease in neutropenic and immunosuppressed patients. Diagnosis combines microscopy, fungal culture, histopathology and assays such as galactomannan where indicated. Voriconazole is a standard first-line treatment for invasive aspergillosis, with treatment tailored to the clinical syndrome.""",
'8a93ff4b-dec0-46b7-b530-0cd2b23dbaed': """Viral causes of exanthems include measles virus, rubella virus, parvovirus B19, human herpesvirus 6 or 7 (roseola), varicella-zoster virus and enteroviruses. The diagnosis depends on the pattern of rash and accompanying signs: cough, coryza and conjunctivitis suggest measles; postauricular lymphadenopathy suggests rubella; and a slapped-cheek appearance suggests parvovirus B19 infection. Vaccination prevents measles, rubella and varicella in eligible populations.""",
'8e337668-c427-41fb-a790-87740d0d5521': """Microbial pathogenicity is determined by the organism's ability to enter the host, adhere, multiply, evade host defences and damage tissues. Major virulence factors include adhesins, capsules, enzymes, exotoxins, endotoxin, antigenic variation, intracellular survival mechanisms and biofilm formation. Host immunity, inoculum size and portal of entry also influence whether exposure results in clinical disease.""",
'ac2e7e9c-80ea-40cb-8f39-8a5ea906c3eb': """Poliomyelitis is prevented chiefly by vaccination with inactivated poliovirus vaccine (IPV) and, where recommended, oral poliovirus vaccine (OPV) according to the national immunisation programme. Safe drinking water, sanitation and hand hygiene reduce faecal-oral transmission. Acute flaccid paralysis surveillance, laboratory confirmation and outbreak immunisation are essential to eradication efforts. There is no antiviral cure for paralytic poliomyelitis; supportive care and rehabilitation remain important.""",
'c7876e6d-9991-4cb7-ab12-d54ae1c43168': """Cryptococcus neoformans is an encapsulated yeast acquired from environmental sources by inhalation. It causes pulmonary disease and subacute meningitis, especially in patients with advanced HIV infection. Microscopy may show narrow-based budding yeasts with a capsule; cryptococcal antigen testing of serum or cerebrospinal fluid is highly useful. HIV-associated cryptococcal meningitis requires an amphotericin B-based induction regimen with flucytosine where available, followed by fluconazole consolidation and maintenance, along with management of raised intracranial pressure.""",
'0fd7c04d-e6b4-4c5f-ad74-11ab59d54b87': """Multinodular goitre is an enlarged thyroid with multiple variably sized nodules resulting from repeated cycles of hyperplasia and involution. The cut surface may show colloid-filled nodules, fibrosis, haemorrhage and cystic degeneration. Most patients are euthyroid, although toxic multinodular goitre may cause thyrotoxicosis. Large glands can produce dysphagia, dyspnoea or tracheal deviation.""",
'1b3f189c-6fe5-4749-a363-3bcbe97bd642': """Colloid goitre is a benign thyroid enlargement with follicles distended by abundant colloid and lined by flattened or low cuboidal follicular epithelium. Grossly, the gland may be diffusely enlarged or nodular. It commonly follows involution of a hyperplastic goitre and may occur with iodine deficiency. Most patients are euthyroid.""",
'292e8609-a700-495c-8fb1-11eab7fd8ff1': """Chronic rheumatic heart disease follows immune-mediated injury after group A streptococcal pharyngitis. The mitral valve is most commonly affected. Gross changes include thickening and fibrosis of valve leaflets, commissural fusion and shortened, thickened chordae tendineae, producing the classical fish-mouth mitral stenosis. Complications include atrial fibrillation, left atrial thrombus, heart failure, infective endocarditis and systemic embolism.""",
'4e01bb8c-cfb9-46ff-b4cf-9c0a53454ae8': """Follicular thyroid adenoma is a solitary, well-circumscribed, usually encapsulated benign follicular neoplasm. Histology shows uniform follicles with variable colloid and no capsular or vascular invasion. Demonstration of invasion distinguishes follicular carcinoma from follicular adenoma; cytology alone cannot reliably make that distinction. It may present as a painless thyroid nodule.""",
'8d33ba14-a6fb-4ea8-b31d-9feee38bbe03': """Splenic infarction results from interruption of arterial blood supply, commonly by thromboembolism or vascular occlusion in haemoglobinopathies. Grossly it produces a pale, wedge-shaped area with its base beneath the capsule and apex towards the hilum. Microscopically the lesion shows coagulative necrosis with subsequent inflammation and fibrosis. Repeated infarctions in sickle-cell disease may lead to autosplenectomy.""",
'a1c688f4-f49a-4373-ab84-87aa7c7e846e': """Autosomal dominant polycystic kidney disease causes bilateral enlargement of the kidneys by numerous cysts of varying sizes in the cortex and medulla. The cysts contain clear, turbid or haemorrhagic fluid and progressively compress functioning renal parenchyma. Common features are hypertension, haematuria, flank pain and progressive chronic kidney disease. Important associations include hepatic cysts and intracranial berry aneurysms.""",
'ade4a19b-c3ff-419b-b72f-3d32720d3a6f': """Fibroadenoma is a common benign, biphasic breast tumour consisting of stromal and epithelial elements. Grossly it is a firm, mobile, well-circumscribed, rubbery nodule with a whorled cut surface. Microscopically, fibrous stroma surrounds or compresses benign ducts in pericanalicular or intracanalicular patterns. It is most common in young women.""",
'b44c5a03-cd37-49ec-8c86-792f4bdac515': """Papillary thyroid carcinoma is a malignant tumour of thyroid follicular cells. Hallmark microscopic features include optically clear nuclei, nuclear grooves, intranuclear pseudoinclusions and overlapping nuclei; psammoma bodies may be present. Papillary structures are common but not essential. It frequently spreads to cervical lymph nodes, and prognosis is usually favourable with appropriate treatment.""",
'bc8d2dd6-4329-4693-876b-5bba99c12ae6': """A viral wart (verruca) is a benign squamous proliferation caused by human papillomavirus. Grossly it is a well-demarcated, rough, hyperkeratotic papule. Microscopy shows papillomatosis, acanthosis, hyperkeratosis and koilocytes, which are squamous cells with perinuclear clearing and irregular nuclei. Common warts often occur on the hands and fingers.""",
'be0a64dc-dc21-488e-b3f6-d906ad296bf2': """Wilms tumour (nephroblastoma) is a malignant embryonal renal tumour of childhood. Grossly it is often a large, soft, well-circumscribed mass with haemorrhage and necrosis. Classic histology is triphasic, comprising blastemal, epithelial and stromal components. It may present with a painless abdominal mass, haematuria or hypertension. Prognosis depends on stage and histology.""",
'c36bd257-c39b-4b30-a360-1cb47c929636': """Atherosclerosis is a chronic disease of medium and large arteries marked by intimal plaques containing a lipid-rich necrotic core and a fibrous cap. Plaques may show foam cells, cholesterol clefts, calcification and neovascularisation. Complications include plaque rupture or erosion, thrombosis, myocardial infarction, ischaemic stroke, aneurysm and peripheral arterial disease.""",
'c7f795b3-c87b-4fbe-a817-18011c6a31fa': """Crohn disease is a chronic inflammatory bowel disease with skip lesions and transmural inflammation, commonly involving the terminal ileum and colon. Gross findings include deep linear ulcers, cobblestoning, strictures and a thickened bowel wall. Histology may show non-caseating granulomas. Complications include fistulae, abscesses, obstruction and malabsorption.""",
'd1ff6c55-e1d1-4369-94b8-591122cf8af8': """Benign prostatic hyperplasia is nodular proliferation of glands and fibromuscular stroma in the transition zone of the prostate. Grossly, the prostate is enlarged and nodular and may compress the urethra. Symptoms include hesitancy, poor urinary stream, nocturia and incomplete bladder emptying. Complications include urinary retention, infection, bladder hypertrophy and obstructive uropathy.""",
'd83bcf6d-fc3a-452d-b06b-f3a344ee7305': """Coronary heart disease is most commonly caused by atherosclerotic narrowing of the coronary arteries. A vulnerable plaque may rupture or erode, triggering superimposed thrombosis and acute myocardial ischaemia or infarction. Chronic stenosis may produce stable angina. Complications include arrhythmias, heart failure, cardiogenic shock and sudden cardiac death.""",
'e033c19b-c81b-4e2c-8d7b-5b9c5a94ff00': """Thyroid follicular adenoma is a benign, encapsulated neoplasm of thyroid follicular cells. Grossly it is usually a solitary, well-defined nodule compressing adjacent tissue. Histology may show microfollicular, normofollicular or macrofollicular patterns without capsular or vascular invasion. Excision and histological examination are used when malignancy cannot be excluded.""",
'e5734f88-30d4-46f7-b5b1-96e1d606b9c9': """Achondroplasia is an autosomal dominant skeletal dysplasia, usually caused by an activating FGFR3 mutation that inhibits endochondral bone growth. Features include disproportionate short-limbed stature, a relatively large head, frontal bossing and midface hypoplasia. Potential complications include foramen magnum stenosis, sleep apnoea and spinal canal stenosis. Intelligence is generally normal.""",
'e89ee329-8980-4a87-b076-e44306d2e85c': """Autosplenectomy is progressive shrinkage and loss of splenic tissue following repeated vaso-occlusive infarctions, classically in sickle-cell anaemia. The spleen becomes small and fibrotic, often with calcification. Loss of splenic function increases susceptibility to infections by encapsulated bacteria, particularly Streptococcus pneumoniae. Vaccination and infection-prevention measures are important.""",

'0c15576e-3db0-45c8-a23c-d06555f06489': """Selective media favour particular organisms by suppressing others; differential media distinguish organisms by visible biochemical reactions. MacConkey agar is selective for many Gram-negative enteric bacilli and differentiates lactose fermenters, which form pink colonies, from non-lactose fermenters. Blood agar is enriched and demonstrates haemolysis. Chocolate agar is enriched for fastidious organisms. Prepare the medium according to the manufacturer's instructions, sterilise appropriately, pour aseptically and check sterility and performance with controls.""",
'2ff06691-6dcb-4baf-b392-e6ded39524bb': """Aseptic technique prevents contamination of cultures, personnel and the work area. Disinfect the bench, wash hands, use appropriate protective equipment, label the medium, and work with sterile instruments and containers. Inoculation transfers a clinical specimen or a pure colony to the correct medium using an aseptic technique. Use the appropriate streaking or inoculation pattern, incubate under the conditions specified for the organism, and examine growth alongside suitable controls. Decontaminate used materials after the procedure.""",
'4df5b27f-4cb8-42b0-9145-a0b09e9e1879': """The Ouchterlony double-immunodiffusion test demonstrates antigen–antibody precipitation in agar. Antigen and antibody diffuse from separate wells; a visible precipitin line forms where they meet at equivalence. Fused lines indicate antigenic identity; crossing lines indicate non-identity; a fused line with a spur indicates partial identity. The test can compare antigenic relatedness but is less sensitive and slower than modern immunoassays.""",
'4ec46317-2549-4d20-a967-3a322f95db79': """A sputum specimen is assessed for quality before interpreting the culture. Numerous squamous epithelial cells suggest salivary contamination; neutrophils and compatible organisms on Gram stain support lower-respiratory inflammation. Culture and identification are interpreted alongside symptoms, radiology and specimen quality because colonising oral flora can grow in sputum. Significant isolates may undergo identification and antimicrobial susceptibility testing. A negative or mixed-flora culture alone does not exclude pneumonia.""",
'5d823ef5-2bb4-426f-b6fd-b96fa954fc32': """An API identification strip contains miniature biochemical tests used to identify a bacterial isolate. A standardised suspension from a pure culture inoculates the test wells. After the prescribed incubation, colour reactions and any added reagents are read as positive or negative. A numerical profile is compared with the manufacturer's identification database. The result must agree with Gram reaction, colony appearance and other basic laboratory findings; inconclusive identifications require further testing.""",
'6f9a2ddf-dbbd-44ef-a9bf-1760f032e978': """Enzyme-linked immunosorbent assay (ELISA) detects an antigen or antibody using specific binding and an enzyme-labelled reagent. The enzyme acts on a substrate to produce a measurable colour signal. Common formats include direct, indirect, sandwich and competitive ELISA. In direct or sandwich assays, greater colour intensity generally indicates more target; competitive assays often have an inverse relationship. Interpret absorbance with positive, negative and blank controls and the assay-specific cut-off, not colour alone.""",
'778277eb-a26e-4649-b5ea-0a94d023342f': """Endospore staining by the Schaeffer–Fulton method uses malachite green with heat to stain bacterial spores; safranin counterstains vegetative cells. Endospores appear green and vegetative cells red or pink. Capsule staining demonstrates a non-staining halo around the organism. India ink is a negative stain that darkens the background; Anthony's method is another technique used for bacterial capsules. Capsule detection depends on the specimen and method, so a negative stain does not always exclude an encapsulated organism.""",
'a6e45cb4-e306-44ab-bccc-9b5905a9ef14': """Viable plate counts estimate the concentration of colony-forming units (CFU) in a sample. Prepare measured serial dilutions, plate a known volume and count colonies on a suitable countable plate. CFU/mL = colony count ÷ (dilution × volume plated in mL). The method estimates viable organisms capable of forming colonies under the selected culture conditions; it does not count every individual bacterial cell. Record dilution, plated volume, count and any contamination.""",
'a8efb759-0a55-465c-b235-85abe8d6bece': """The minimum inhibitory concentration (MIC) is the lowest antimicrobial concentration that prevents visible growth of a standardised organism under defined conditions. Broth dilution uses a series of antimicrobial concentrations, a standardised bacterial inoculum and growth/sterility controls. The MIC is read at the first concentration without visible growth and interpreted using organism-specific clinical breakpoints where available. MIC does not necessarily equal the minimum bactericidal concentration (MBC).""",
'afa5bd15-9a0e-4d57-b0b7-3bf04bc03c44': """A bacterial growth curve in a closed culture has four main phases: lag, exponential or log, stationary, and death. In the lag phase cells adapt; in the log phase the population divides rapidly; in stationary phase growth balances death as nutrients diminish and wastes accumulate; in death phase viable counts decline. Temperature affects enzyme activity, membrane function and growth rate. Organisms have minimum, optimum and maximum growth temperatures; temperatures beyond tolerance inhibit growth or kill the organisms.""",
'b147f643-063a-4989-a597-5c4ba681de49': """A potassium hydroxide (KOH) wet mount clears keratin and cellular material, allowing fungal hyphae or yeasts to be seen in a clinical specimen. Lactophenol cotton blue is commonly used to examine fungal structures from a culture; cotton blue stains chitin in fungal cell walls, while the mounting medium preserves the preparation. Interpret septation, branching, conidiophores and spores together with culture and clinical findings. These stains do not replace species confirmation when needed.""",
'c17d7528-e6ab-44a6-839c-78f7f3499528': """Blood agar is an enriched medium, commonly containing about 5% defibrinated sheep blood, and distinguishes alpha, beta and non-haemolytic colony reactions. MacConkey agar contains bile salts and crystal violet that inhibit many Gram-positive organisms; lactose fermenters produce pink colonies because of the neutral-red indicator, while non-lactose fermenters are usually pale. Both media require quality-control checks for sterility and expected growth reactions.""",
'd6341c68-4b6d-4e2d-a27c-b2d0fffa89b7': """Chocolate agar is an enriched medium in which heated blood releases growth factors needed by fastidious bacteria, including Neisseria species. Suspected Neisseria isolates are assessed using colony morphology, Gram stain, oxidase reaction and confirmatory biochemical or molecular tests. Some species require added carbon dioxide and careful transport of clinical material. Interpretation must distinguish pathogenic Neisseria from commensal species and follow laboratory biosafety procedures.""",
'dd352fb7-fb7c-4fe7-8c86-7fe925330959': """Stool culture investigates bacterial causes of infectious diarrhoea. The specimen is collected without urine contamination and transported promptly. Depending on the clinical request, laboratories use selective or differential media and confirm suspect isolates by biochemical, antigenic or molecular methods. Salmonella and Shigella may be sought on appropriate enteric media; other pathogens require different assays. Results are interpreted with symptoms, travel history, antibiotic exposure and local epidemiology. Routine culture does not detect every enteric pathogen.""",
'df163b6f-2022-4a8e-9afa-66452d3d6dbe': """Phage typing differentiates strains of a bacterial species by their susceptibility to a standard panel of bacteriophages. Lysis produces clear zones where a phage infects and destroys a susceptible bacterial lawn. The pattern is recorded as a phage type and may support epidemiological tracing. The method requires validated reference panels and has largely been superseded in many settings by molecular typing and whole-genome sequencing.""",
'e0b76d40-fe6a-420a-a137-2951a72ff310': """Broth dilution determines the minimum inhibitory concentration of an antimicrobial agent. A standardised bacterial suspension is tested against serial antimicrobial concentrations with suitable growth and sterility controls. After incubation, the MIC is the lowest concentration showing no visible growth. Interpret the result with current susceptibility breakpoints and the organism identified; the MIC alone does not describe clinical effectiveness in every tissue or patient.""",
'cd60c9c5-5cd7-448d-b210-d20fa800adc2': """Mean corpuscular volume (MCV) is the average red-cell volume, normally about 80–100 fL in adults. MCV (fL) = haematocrit (%) × 10 ÷ red-cell count (million/µL). Mean corpuscular haemoglobin (MCH) is the average haemoglobin mass per red cell: haemoglobin (g/dL) × 10 ÷ red-cell count (million/µL), normally about 27–33 pg. Mean corpuscular haemoglobin concentration (MCHC) is haemoglobin concentration within packed red cells: haemoglobin (g/dL) × 100 ÷ haematocrit (%), normally about 32–36 g/dL. Laboratory intervals vary.""",
'53cb4ef5-8339-4b3a-a4a8-6af6dd811074': """The posterior iliac crest is the preferred site for bone-marrow aspiration in adults and most children because it is accessible and generally safe. The sternum may be used selectively for aspiration in adults but not for trephine biopsy because of injury risk; the proximal tibia is occasionally used in small infants by appropriately trained staff. Indications include unexplained cytopenias, suspected leukaemia or marrow infiltration, selected lymphoma staging, and evaluation of marrow failure or storage disorders. An aspirate assesses cellular morphology; a trephine biopsy assesses architecture and cellularity.""",

}

def main():
    if os.getenv('LENXIQ_PROJECT_REF')!=PROJECT:raise RuntimeError('Wrong Supabase project')
    count=0
    for ident,answer in ANSWERS.items():
        row=snapshot(ident)
        original=row.get('model_answer')
        if original is not None and len(original.strip())>70:
            if original==answer:continue
            raise RuntimeError('Existing detailed answer will not be overwritten: '+ident)
        if original is not None and original.strip() and original.strip()!=row.get('question_text','').strip() and original.strip()!=answer:
            raise RuntimeError('Non-placeholder model answer needs review: '+ident)
        count+=apply_one(ident,{'model_answer':original},{'model_answer':answer})
    print('Verified completed medical theory and named practical answers:',count)
    if os.getenv('GITHUB_STEP_SUMMARY'):
        with open(os.environ['GITHUB_STEP_SUMMARY'],'a',encoding='utf-8') as f:
            f.write('\n- Additional completed theory and named practical answers: **'+str(count)+'**\n')

if __name__=='__main__':main()
